import type { NextConfig } from 'next'

const api = process.env.API_URL ?? 'http://localhost:8000'
const apiHost = new URL(api)

const config: NextConfig = {
  poweredByHeader: false,
  reactStrictMode: true,
  // Pictures come from the API already resized (WebP/AVIF srcset), so the Next optimizer is not needed and would only re-encode them.
  images: { unoptimized: true, remotePatterns: [{ protocol: apiHost.protocol.replace(':', '') as 'http' | 'https', hostname: apiHost.hostname }] },
  // Crawler and browser files are generated by the API from the published settings (base URL, noindex paths, theme icons): serve them as ours.
  async rewrites() {
    return ['/robots.txt', '/sitemap.xml', '/sitemaps/:name.xml', '/manifest.webmanifest', '/favicon.ico'].map((source) => ({ source, destination: `${api.replace(/\/$/, '')}${source}` }))
  },
  async headers() {
    return [
      {
        source: '/:path*',
        headers: [
          { key: 'X-Content-Type-Options', value: 'nosniff' },
          { key: 'Referrer-Policy', value: 'strict-origin-when-cross-origin' },
          { key: 'X-Frame-Options', value: 'SAMEORIGIN' },
          { key: 'Permissions-Policy', value: 'camera=(), microphone=(), geolocation=(), payment=(self "https://js.stripe.com")' },
          { key: 'Cross-Origin-Opener-Policy', value: 'same-origin-allow-popups' }, // popups (PayPal, Stripe 3-D Secure) must keep working
          ...(process.env.NODE_ENV === 'production' ? [{ key: 'Strict-Transport-Security', value: 'max-age=63072000; includeSubDomains' }] : []),
        ],
      },
    ]
  },
}

export default config
